SELECT Имена_станций.NAME, Имена_ОЭС.abbr AS oesname, Имена_областей.abbr AS oblname, Имена_станций.ordnumb, [Станции(архив)].year, [Станции(архив)].nust, [Станции(архив)].E, [Станции(архив)].eotp, [Станции(архив)].eurt, [Станции(архив)].eust, [Станции(архив)].Q, [Станции(архив)].turt, [Станции(архив)].tust, [Станции(архив)].B, [Станции(архив)].gaz, [Станции(архив)].mazut, [Станции(архив)].torf, [Станции(архив)].slan, [Станции(архив)].gtt AS Выражение1, [Станции(архив)].proch, [Станции(архив)].ugol, [Станции(архив)].don, [Станции(архив)].podm, [Станции(архив)].pech, [Доп_угли(архив)].int, [Доп_угли(архив)].vork, [Станции(архив)].arkt, [Станции(архив)].kuzn, [Станции(архив)].ural, [Доп_угли(архив)].sver, [Доп_угли(архив)].chel, [Доп_угли(архив)].kizel, [Станции(архив)].bashk, [Станции(архив)].ekib AS Выражение2, [Станции(архив)].karag, [Станции(архив)].kan, [Доп_угли(архив)].nazar, [Доп_угли(архив)].ibor, [Доп_угли(архив)].berez, [Доп_угли(архив)].per, [Станции(архив)].irkut, [Доп_угли(архив)].azey, [Доп_угли(архив)].cher, [Станции(архив)].hak, [Станции(архив)].tuv, [Станции(архив)].bur, [Доп_угли(архив)].gusin, [Доп_угли(архив)].tugn, [Станции(архив)].chit, [Станции(архив)].ner AS Выражение3, [Станции(архив)].raich AS Выражение4, [Станции(архив)].urg, [Станции(архив)].prim, [Станции(архив)].luch, [Станции(архив)].mag, [Станции(архив)].sah, [Станции(архив)].qotr, [Станции(архив)].snk, [Станции(архив)].ewtp, [Станции(архив)].nt, [Станции(архив)].obor, [Станции(архив)].ved, [Станции(архив)].obl, [Станции(архив)].dep, [Станции(архив)].oes, [Станции(архив)].er, [Станции(архив)].numb1120, IIf([ved]<3,1,2) AS вед, IIf([ved]=1 Or [ved]=4,1,IIf([ved]=2 Or [ved]=3,2,0)) AS кэстэц, Имена_станций.D, Имена_станций.R
FROM ((([Станции(архив)] INNER JOIN Имена_станций ON [Станции(архив)].numb1120=Имена_станций.NUMB) INNER JOIN Имена_ОЭС ON [Станции(архив)].oes=Имена_ОЭС.oes) INNER JOIN Имена_областей ON [Станции(архив)].obl=Имена_областей.OBL) LEFT JOIN [Доп_угли(архив)] ON ([Станции(архив)].year=[Доп_угли(архив)].YEAR) AND ([Станции(архив)].numb1120=[Доп_угли(архив)].NUMB1120)
WHERE ((([Станции(архив)].year)=2000) AND (([Станции(архив)].ved)>0));
